-- mutant m14-tick-writes-is-checked (generated by generate.mjs from supabase/migrations/20260925073000_backlog_3477_submission_checklist_review.sql; do not edit)
-- targets: c05
-- BACKLOG-3477: reviewing a submission's checklists in the broker portal.
--
-- What this file adds (one file, applied in one transaction; it opens none of
-- its own, and every statement is safe to run twice):
--
--   1. submission_checklist_items: reviewer_checked / _by / _at (the
--      reviewer's layer, separate from the agent's is_checked), plus nullable
--      description and expected_document_type so the frozen copy matches the
--      agent's item.
--   2. submission_checklists: added_at_review_by / _at (a checklist a reviewer
--      added for the agent's next version) and one checklist per template per
--      submission.
--   3. public.can_review_submission(org): the ONE list of roles that may read
--      and review an organization's submissions (broker, admin, it_admin).
--      Every widened read rule and both reviewer functions call it; no other
--      role list for submission review exists in this file.
--   4. Read rules on transaction_submissions, submission_messages,
--      submission_attachments and the four checklist copy tables re-created
--      through that helper.
--   5. The submitter's INSERT rules on checklist headers and items refuse rows
--      that already carry reviewer / added-at-review values.
--   6. public.snapshot_submission_checklists(submission, payload): the whole
--      checklist copy of one submission in one call (SECURITY INVOKER: the
--      INSERT rules above stay the only authority).
--   7. public.set_submission_checklist_reviewer_check(item, checked): the
--      reviewer tick, with one Status History entry per change.
--   8. public.add_submission_checklist_at_review(submission, template): add one
--      of the organization's own templates to a submission under review, with
--      one Status History entry.
--   9. transaction_submissions.status_history accepts appends only: a new row
--      starts with an empty history, existing entries cannot be changed or
--      removed, and every appended entry must be typed and name the caller as
--      changed_by. The service role and sessions with no request JWT are
--      exempt.
--
-- Status History entry shape written here (typed, append-only):
--   required  type, changed_at, changed_by (raw user id)
--   optional  reason, field, from, to, and entry-specific keys
--   never     status (status entries are written by track_submission_status_changes)
--
-- Errors raised by the functions:
--   42501 not_authorized      no signed-in caller, not a reviewer of the
--                             submission's organization, unknown item or
--                             submission, or the feature is off
--   42501 not_open_for_review the submission's status does not allow the change
--   42501 added_at_review     the item belongs to a checklist added at review
--   42501 status_history_append_only  a new row with a non-empty history, a
--                             rewrite or removal of an entry, or an appended
--                             entry without a type or naming someone else
--   22023 invalid_payload / invalid_argument
--
-- Rollback (reverse order):
--   DROP TRIGGER IF EXISTS status_history_append_only ON public.transaction_submissions;
--   DROP FUNCTION public.guard_status_history_append_only();
--   DROP FUNCTION public.add_submission_checklist_at_review(uuid, uuid);
--   DROP FUNCTION public.set_submission_checklist_reviewer_check(uuid, boolean);
--   DROP FUNCTION public.snapshot_submission_checklists(uuid, jsonb);
--   re-create the seven SELECT policies and two INSERT policies from
--     20260921101757_backlog_3473_transaction_checklists.sql and the baseline;
--   DROP FUNCTION public.can_review_submission(uuid);
--   DROP INDEX public.submission_checklists_submission_template_key;
--   ALTER TABLE ... DROP COLUMN for the seven columns and two constraints.

-- ---------------------------------------------------------------------------
-- 1. Item columns
-- ---------------------------------------------------------------------------
ALTER TABLE public.submission_checklist_items
  ADD COLUMN IF NOT EXISTS reviewer_checked boolean NOT NULL DEFAULT false,
  ADD COLUMN IF NOT EXISTS reviewer_checked_by uuid NULL,
  ADD COLUMN IF NOT EXISTS reviewer_checked_at timestamptz NULL,
  ADD COLUMN IF NOT EXISTS description text NULL,
  ADD COLUMN IF NOT EXISTS expected_document_type text NULL;

-- ---------------------------------------------------------------------------
-- 2. Header columns and one checklist per template per submission
-- ---------------------------------------------------------------------------
ALTER TABLE public.submission_checklists
  ADD COLUMN IF NOT EXISTS added_at_review_by uuid NULL,
  ADD COLUMN IF NOT EXISTS added_at_review_at timestamptz NULL;

DO $constraints$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_constraint
                  WHERE conname = 'submission_checklist_items_reviewer_pair_check'
                    AND conrelid = 'public.submission_checklist_items'::regclass) THEN
    ALTER TABLE public.submission_checklist_items
      ADD CONSTRAINT submission_checklist_items_reviewer_pair_check
      CHECK (reviewer_checked = (reviewer_checked_by IS NOT NULL AND reviewer_checked_at IS NOT NULL)
             AND (reviewer_checked_by IS NULL) = (reviewer_checked_at IS NULL));
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint
                  WHERE conname = 'submission_checklists_added_at_review_pair_check'
                    AND conrelid = 'public.submission_checklists'::regclass) THEN
    ALTER TABLE public.submission_checklists
      ADD CONSTRAINT submission_checklists_added_at_review_pair_check
      CHECK ((added_at_review_by IS NULL) = (added_at_review_at IS NULL));
  END IF;
END
$constraints$;

CREATE UNIQUE INDEX IF NOT EXISTS submission_checklists_submission_template_key
  ON public.submission_checklists (submission_id, template_id)
  WHERE template_id IS NOT NULL;

-- ---------------------------------------------------------------------------
-- 3. Who may read and review an organization's submissions. The one place
--    the role list lives.
-- ---------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.can_review_submission(p_org_id uuid)
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = ''
AS $$
  SELECT EXISTS (
    SELECT 1
      FROM public.organization_members om
     WHERE om.organization_id = p_org_id
       AND om.user_id = (SELECT auth.uid())
       AND om.role IN ('broker', 'admin', 'it_admin')
  );
$$;

-- anon keeps EXECUTE: the transaction_submissions, submission_messages and
-- submission_attachments read rules apply to every role, and without it an
-- anon read would error instead of returning no rows. It returns false for
-- a caller with no user id.
REVOKE EXECUTE ON FUNCTION public.can_review_submission(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.can_review_submission(uuid) TO anon, authenticated;

-- ---------------------------------------------------------------------------
-- 4. Read rules through the helper (same names, same roles as before)
-- ---------------------------------------------------------------------------
DROP POLICY IF EXISTS transaction_submissions_select_public ON public.transaction_submissions;
CREATE POLICY transaction_submissions_select_public ON public.transaction_submissions
  FOR SELECT TO public
  USING (submitted_by = (SELECT auth.uid())
         OR public.can_review_submission(organization_id));

DROP POLICY IF EXISTS message_access_via_submission ON public.submission_messages;
CREATE POLICY message_access_via_submission ON public.submission_messages
  FOR SELECT TO public
  USING (EXISTS (
    SELECT 1
      FROM public.transaction_submissions ts
     WHERE ts.id = submission_messages.submission_id
       AND (ts.submitted_by = (SELECT auth.uid())
            OR public.can_review_submission(ts.organization_id))
  ));

DROP POLICY IF EXISTS attachment_access_via_submission ON public.submission_attachments;
CREATE POLICY attachment_access_via_submission ON public.submission_attachments
  FOR SELECT TO public
  USING (EXISTS (
    SELECT 1
      FROM public.transaction_submissions ts
     WHERE ts.id = submission_attachments.submission_id
       AND (ts.submitted_by = (SELECT auth.uid())
            OR public.can_review_submission(ts.organization_id))
  ));

DROP POLICY IF EXISTS submission_checklists_select ON public.submission_checklists;
CREATE POLICY submission_checklists_select ON public.submission_checklists
  FOR SELECT TO authenticated
  USING (EXISTS (
    SELECT 1
      FROM public.transaction_submissions ts
     WHERE ts.id = submission_checklists.submission_id
       AND (ts.submitted_by = (SELECT auth.uid())
            OR public.can_review_submission(ts.organization_id))
  ));

DROP POLICY IF EXISTS submission_checklist_items_select ON public.submission_checklist_items;
CREATE POLICY submission_checklist_items_select ON public.submission_checklist_items
  FOR SELECT TO authenticated
  USING (EXISTS (
    SELECT 1
      FROM public.transaction_submissions ts
     WHERE ts.id = submission_checklist_items.submission_id
       AND (ts.submitted_by = (SELECT auth.uid())
            OR public.can_review_submission(ts.organization_id))
  ));

DROP POLICY IF EXISTS submission_checklist_links_select ON public.submission_checklist_links;
CREATE POLICY submission_checklist_links_select ON public.submission_checklist_links
  FOR SELECT TO authenticated
  USING (EXISTS (
    SELECT 1
      FROM public.transaction_submissions ts
     WHERE ts.id = submission_checklist_links.submission_id
       AND (ts.submitted_by = (SELECT auth.uid())
            OR public.can_review_submission(ts.organization_id))
  ));

DROP POLICY IF EXISTS submission_checklist_link_members_select ON public.submission_checklist_link_members;
CREATE POLICY submission_checklist_link_members_select ON public.submission_checklist_link_members
  FOR SELECT TO authenticated
  USING (EXISTS (
    SELECT 1
      FROM public.transaction_submissions ts
     WHERE ts.id = submission_checklist_link_members.submission_id
       AND (ts.submitted_by = (SELECT auth.uid())
            OR public.can_review_submission(ts.organization_id))
  ));

-- ---------------------------------------------------------------------------
-- 5. The submitter's INSERT rules: never a reviewer value
-- ---------------------------------------------------------------------------
DROP POLICY IF EXISTS submission_checklists_insert ON public.submission_checklists;
CREATE POLICY submission_checklists_insert ON public.submission_checklists
  FOR INSERT TO authenticated
  WITH CHECK (
    submission_checklists.added_at_review_by IS NULL
    AND submission_checklists.added_at_review_at IS NULL
    AND EXISTS (
      SELECT 1
        FROM public.transaction_submissions ts
       WHERE ts.id = submission_checklists.submission_id
         AND ts.submitted_by = (SELECT auth.uid())
         AND ts.status = 'uploading'
         AND COALESCE((public.check_feature_access(ts.organization_id, 'transaction_checklists') ->> 'allowed')::boolean, false)
    )
  );

DROP POLICY IF EXISTS submission_checklist_items_insert ON public.submission_checklist_items;
CREATE POLICY submission_checklist_items_insert ON public.submission_checklist_items
  FOR INSERT TO authenticated
  WITH CHECK (
    submission_checklist_items.reviewer_checked = false
    AND submission_checklist_items.reviewer_checked_by IS NULL
    AND submission_checklist_items.reviewer_checked_at IS NULL
    AND EXISTS (
      SELECT 1
        FROM public.transaction_submissions ts
       WHERE ts.id = submission_checklist_items.submission_id
         AND ts.submitted_by = (SELECT auth.uid())
         AND ts.status = 'uploading'
    )
  );

-- ---------------------------------------------------------------------------
-- 6. The desktop's snapshot: every checklist of one submission in one call.
--
--   p_checklists: JSON array of
--     {template_id?, template_name, sort_order?,
--      items: [{title, description?, is_required?, expected_document_type?,
--               is_checked?, note?, sort_order?,
--               links: [{kind: 'attachment'|'email', label, sort_order?,
--                        local_ids: [text, ...]}]}]}
--   A link's local ids are matched to this submission's rows:
--     attachment -> submission_attachments.local_attachment_id (every match)
--     email      -> submission_messages.local_message_id, channel 'email'
--   A local id with no match is dropped; a link left with no member is not
--   written. Returns counts. Any refusal rolls back the whole call.
-- ---------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.snapshot_submission_checklists(
  p_submission_id uuid,
  p_checklists jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path = ''
AS $$
DECLARE
  c            jsonb;
  it           jsonb;
  lk           jsonb;
  v_header_id  uuid;
  v_item_id    uuid;
  v_link_id    uuid;
  v_kind       text;
  v_local_ids  text[];
  v_targets    uuid[];
  v_asked      integer;
  v_link_dropped integer;
  n_checklists integer := 0;
  n_items      integer := 0;
  n_links      integer := 0;
  n_members    integer := 0;
  n_dropped_members integer := 0;
  n_dropped_links   integer := 0;
BEGIN
  IF p_submission_id IS NULL OR p_checklists IS NULL OR jsonb_typeof(p_checklists) <> 'array' THEN
    RAISE EXCEPTION 'invalid_payload' USING ERRCODE = '22023';
  END IF;

  FOR c IN SELECT e.value FROM jsonb_array_elements(p_checklists) AS e(value) LOOP
    IF jsonb_typeof(c) <> 'object'
       OR (c ? 'items' AND jsonb_typeof(c -> 'items') <> 'array') THEN
      RAISE EXCEPTION 'invalid_payload' USING ERRCODE = '22023';
    END IF;

    INSERT INTO public.submission_checklists (submission_id, template_id, template_name, sort_order)
    VALUES (p_submission_id,
            NULLIF(c ->> 'template_id', '')::uuid,
            c ->> 'template_name',
            COALESCE((c ->> 'sort_order')::integer, 0))
    RETURNING id INTO v_header_id;
    n_checklists := n_checklists + 1;

    FOR it IN SELECT e.value FROM jsonb_array_elements(COALESCE(c -> 'items', '[]'::jsonb)) AS e(value) LOOP
      IF jsonb_typeof(it) <> 'object'
         OR (it ? 'links' AND jsonb_typeof(it -> 'links') <> 'array') THEN
        RAISE EXCEPTION 'invalid_payload' USING ERRCODE = '22023';
      END IF;

      INSERT INTO public.submission_checklist_items
        (submission_id, submission_checklist_id, title, description, is_required,
         expected_document_type, is_checked, note, sort_order)
      VALUES (p_submission_id, v_header_id,
              it ->> 'title',
              it ->> 'description',
              COALESCE((it ->> 'is_required')::boolean, false),
              it ->> 'expected_document_type',
              COALESCE((it ->> 'is_checked')::boolean, false),
              it ->> 'note',
              COALESCE((it ->> 'sort_order')::integer, 0))
      RETURNING id INTO v_item_id;
      n_items := n_items + 1;

      FOR lk IN SELECT e.value FROM jsonb_array_elements(COALESCE(it -> 'links', '[]'::jsonb)) AS e(value) LOOP
        v_kind := lk ->> 'kind';
        IF jsonb_typeof(lk) <> 'object'
           OR v_kind IS NULL OR v_kind NOT IN ('attachment', 'email')
           OR (lk ? 'local_ids' AND jsonb_typeof(lk -> 'local_ids') <> 'array') THEN
          RAISE EXCEPTION 'invalid_payload' USING ERRCODE = '22023';
        END IF;

        SELECT COALESCE(array_agg(DISTINCT x.value), '{}')
          INTO v_local_ids
          FROM jsonb_array_elements_text(COALESCE(lk -> 'local_ids', '[]'::jsonb)) AS x(value);
        v_asked := COALESCE(cardinality(v_local_ids), 0);

        IF v_kind = 'attachment' THEN
          SELECT COALESCE(array_agg(a.id), '{}'), v_asked - count(DISTINCT a.local_attachment_id)::integer
            INTO v_targets, v_link_dropped
            FROM public.submission_attachments a
           WHERE a.submission_id = p_submission_id
             AND a.local_attachment_id = ANY (v_local_ids);
        ELSE
          SELECT COALESCE(array_agg(m.id), '{}'), v_asked - count(DISTINCT m.local_message_id)::integer
            INTO v_targets, v_link_dropped
            FROM public.submission_messages m
           WHERE m.submission_id = p_submission_id
             AND m.channel = 'email'
             AND m.local_message_id = ANY (v_local_ids);
        END IF;
        n_dropped_members := n_dropped_members + v_link_dropped;

        IF COALESCE(cardinality(v_targets), 0) = 0 THEN
          n_dropped_links := n_dropped_links + 1;
          CONTINUE;
        END IF;

        INSERT INTO public.submission_checklist_links
          (submission_id, submission_checklist_item_id, kind, label, sort_order)
        VALUES (p_submission_id, v_item_id, v_kind, lk ->> 'label',
                COALESCE((lk ->> 'sort_order')::integer, 0))
        RETURNING id INTO v_link_id;
        n_links := n_links + 1;

        IF v_kind = 'attachment' THEN
          INSERT INTO public.submission_checklist_link_members
            (submission_id, link_id, kind, submission_attachment_id)
          SELECT p_submission_id, v_link_id, 'attachment', t.id
            FROM unnest(v_targets) AS t(id)
          ON CONFLICT (link_id, submission_attachment_id) DO NOTHING;
        ELSE
          INSERT INTO public.submission_checklist_link_members
            (submission_id, link_id, kind, submission_message_id)
          SELECT p_submission_id, v_link_id, 'email', t.id
            FROM unnest(v_targets) AS t(id)
          ON CONFLICT (link_id, submission_message_id) DO NOTHING;
        END IF;
        n_members := n_members + cardinality(v_targets);
      END LOOP;
    END LOOP;
  END LOOP;

  RETURN jsonb_build_object(
    'checklists', n_checklists,
    'items', n_items,
    'links', n_links,
    'members', n_members,
    'dropped_members', n_dropped_members,
    'dropped_links', n_dropped_links);
END
$$;

REVOKE EXECUTE ON FUNCTION public.snapshot_submission_checklists(uuid, jsonb) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.snapshot_submission_checklists(uuid, jsonb) TO authenticated;

-- ---------------------------------------------------------------------------
-- 7. The reviewer tick. Writes only the reviewer columns (never is_checked)
--    and appends one typed Status History entry when the value changes.
-- ---------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.set_submission_checklist_reviewer_check(
  p_item_id uuid,
  p_checked boolean
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_uid    uuid := auth.uid();
  v_now    timestamptz := now();
  v_row    record;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'not_authorized' USING ERRCODE = '42501';
  END IF;
  IF p_item_id IS NULL OR p_checked IS NULL THEN
    RAISE EXCEPTION 'invalid_argument' USING ERRCODE = '22023';
  END IF;

  SELECT i.id, i.title, i.reviewer_checked, i.submission_id,
         h.template_name, h.added_at_review_by,
         ts.organization_id, ts.status
    INTO v_row
    FROM public.submission_checklist_items i
    JOIN public.submission_checklists h ON h.id = i.submission_checklist_id
    JOIN public.transaction_submissions ts ON ts.id = i.submission_id
   WHERE i.id = p_item_id
     FOR UPDATE OF i;

  IF NOT FOUND OR NOT public.can_review_submission(v_row.organization_id) THEN
    RAISE EXCEPTION 'not_authorized' USING ERRCODE = '42501';
  END IF;
  IF NOT COALESCE((public.check_feature_access(v_row.organization_id, 'transaction_checklists') ->> 'allowed')::boolean, false) THEN
    RAISE EXCEPTION 'not_authorized' USING ERRCODE = '42501';
  END IF;
  IF v_row.status IS NULL
     OR v_row.status NOT IN ('submitted', 'resubmitted', 'under_review', 'needs_changes') THEN
    RAISE EXCEPTION 'not_open_for_review' USING ERRCODE = '42501';
  END IF;
  IF v_row.added_at_review_by IS NOT NULL THEN
    RAISE EXCEPTION 'added_at_review' USING ERRCODE = '42501';
  END IF;

  IF v_row.reviewer_checked = p_checked THEN
    RETURN jsonb_build_object('changed', false, 'reviewer_checked', p_checked);
  END IF;

  UPDATE public.submission_checklist_items
     SET reviewer_checked    = p_checked,
         is_checked          = p_checked,
         reviewer_checked_by = CASE WHEN p_checked THEN v_uid END,
         reviewer_checked_at = CASE WHEN p_checked THEN v_now END
   WHERE id = p_item_id;

  -- One statement: the append reads the row's current history under the row
  -- lock, so concurrent ticks on one submission never lose an entry.
  UPDATE public.transaction_submissions
     SET status_history = COALESCE(status_history, '[]'::jsonb) || jsonb_build_array(jsonb_build_object(
           'type', 'checklist_review',
           'changed_at', v_now,
           'changed_by', v_uid,
           'field', 'reviewer_checked',
           'from', v_row.reviewer_checked,
           'to', p_checked,
           'item_id', v_row.id,
           'item_title', v_row.title,
           'checklist_name', v_row.template_name))
   WHERE id = v_row.submission_id;

  RETURN jsonb_build_object(
    'changed', true,
    'reviewer_checked', p_checked,
    'reviewer_checked_by', CASE WHEN p_checked THEN v_uid END,
    'reviewer_checked_at', CASE WHEN p_checked THEN v_now END);
END
$$;

REVOKE EXECUTE ON FUNCTION public.set_submission_checklist_reviewer_check(uuid, boolean) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.set_submission_checklist_reviewer_check(uuid, boolean) TO authenticated;

-- ---------------------------------------------------------------------------
-- 8. Add one of the organization's templates to a submission under review.
--    Returns {status: 'added' | 'exists' | 'template_not_found', ...}.
-- ---------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.add_submission_checklist_at_review(
  p_submission_id uuid,
  p_template_id uuid
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_uid       uuid := auth.uid();
  v_now       timestamptz := now();
  v_sub       record;
  v_tpl       record;
  v_header_id uuid;
  v_items     integer;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'not_authorized' USING ERRCODE = '42501';
  END IF;
  IF p_submission_id IS NULL OR p_template_id IS NULL THEN
    RAISE EXCEPTION 'invalid_argument' USING ERRCODE = '22023';
  END IF;

  SELECT ts.id, ts.organization_id, ts.status
    INTO v_sub
    FROM public.transaction_submissions ts
   WHERE ts.id = p_submission_id
     FOR UPDATE;

  IF NOT FOUND OR NOT public.can_review_submission(v_sub.organization_id) THEN
    RAISE EXCEPTION 'not_authorized' USING ERRCODE = '42501';
  END IF;
  IF NOT COALESCE((public.check_feature_access(v_sub.organization_id, 'transaction_checklists') ->> 'allowed')::boolean, false) THEN
    RAISE EXCEPTION 'not_authorized' USING ERRCODE = '42501';
  END IF;
  IF v_sub.status IS NULL OR v_sub.status NOT IN ('submitted', 'resubmitted', 'under_review') THEN
    RAISE EXCEPTION 'not_open_for_review' USING ERRCODE = '42501';
  END IF;

  SELECT t.id, t.name
    INTO v_tpl
    FROM public.checklist_templates t
   WHERE t.id = p_template_id
     AND t.organization_id = v_sub.organization_id
     AND t.archived_at IS NULL;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('status', 'template_not_found');
  END IF;

  SELECT h.id INTO v_header_id
    FROM public.submission_checklists h
   WHERE h.submission_id = p_submission_id
     AND h.template_id = p_template_id;
  IF FOUND THEN
    RETURN jsonb_build_object('status', 'exists', 'checklist_id', v_header_id);
  END IF;

  INSERT INTO public.submission_checklists
    (submission_id, template_id, template_name, sort_order, added_at_review_by, added_at_review_at)
  VALUES (p_submission_id, v_tpl.id, v_tpl.name,
          COALESCE((SELECT max(h.sort_order) + 1 FROM public.submission_checklists h
                     WHERE h.submission_id = p_submission_id), 0),
          v_uid, v_now)
  RETURNING id INTO v_header_id;

  INSERT INTO public.submission_checklist_items
    (submission_id, submission_checklist_id, title, description, is_required,
     expected_document_type, is_checked, sort_order)
  SELECT p_submission_id, v_header_id, ti.title, ti.description, ti.is_required,
         ti.expected_document_type, false, ti.sort_order
    FROM public.checklist_template_items ti
   WHERE ti.template_id = v_tpl.id;
  GET DIAGNOSTICS v_items = ROW_COUNT;

  UPDATE public.transaction_submissions
     SET status_history = COALESCE(status_history, '[]'::jsonb) || jsonb_build_array(jsonb_build_object(
           'type', 'checklist_added',
           'changed_at', v_now,
           'changed_by', v_uid,
           'checklist_id', v_header_id,
           'checklist_name', v_tpl.name,
           'template_id', v_tpl.id))
   WHERE id = p_submission_id;

  RETURN jsonb_build_object('status', 'added', 'checklist_id', v_header_id, 'items', v_items);
END
$$;

REVOKE EXECUTE ON FUNCTION public.add_submission_checklist_at_review(uuid, uuid) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.add_submission_checklist_at_review(uuid, uuid) TO authenticated;

-- ---------------------------------------------------------------------------
-- 9. status_history accepts appends only.
--
--    Exempt: auth.role() IS NULL (no request JWT: migrations, maintenance)
--    and auth.role() = 'service_role'. A SECURITY DEFINER function called
--    through the API still carries the caller's JWT, so it is NOT exempt and
--    its appends must pass the same test.
--
--    INSERT: a new row must start with a NULL or empty history.
--
--    UPDATE: every appended entry must be a typed object naming the caller.
--    BEFORE UPDATE triggers fire in name order, so this one
--    ("status_history_append_only") fires before "track_status_changes" and
--    never sees the untyped status entry that trigger appends. The test
--    depends on that order: if it were reversed, every status change by a
--    non-exempt caller would be refused.
-- ---------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.guard_status_history_append_only()
RETURNS trigger
LANGUAGE plpgsql
SET search_path = ''
AS $$
DECLARE
  v_role    text := auth.role();
  v_old     jsonb;
  v_new     jsonb := NEW.status_history;
  v_old_len integer;
  v_new_len integer;
  v_elem    jsonb;
  i         integer;
BEGIN
  IF v_role IS NULL OR v_role = 'service_role' THEN
    RETURN NEW;
  END IF;
  IF TG_OP = 'INSERT' THEN
    IF v_new IS NOT NULL AND v_new <> '[]'::jsonb THEN
      RAISE EXCEPTION 'status_history_append_only' USING ERRCODE = '42501';
    END IF;
    RETURN NEW;
  END IF;
  IF NEW.status_history IS NOT DISTINCT FROM OLD.status_history THEN
    RETURN NEW;
  END IF;

  v_old := COALESCE(OLD.status_history, '[]'::jsonb);
  IF jsonb_typeof(v_old) <> 'array' THEN
    v_old := '[]'::jsonb;
  END IF;
  IF v_new IS NULL OR jsonb_typeof(v_new) <> 'array' THEN
    RAISE EXCEPTION 'status_history_append_only' USING ERRCODE = '42501';
  END IF;

  v_old_len := jsonb_array_length(v_old);
  v_new_len := jsonb_array_length(v_new);

  -- Every existing entry must still be there, unchanged, at the same index.
  -- (A shorter array fails here too: the missing index reads as NULL.)
  FOR i IN 0 .. v_old_len - 1 LOOP
    IF (v_new -> i) IS DISTINCT FROM (v_old -> i) THEN
      RAISE EXCEPTION 'status_history_append_only' USING ERRCODE = '42501';
    END IF;
  END LOOP;

  -- Every appended entry must be a typed object naming the caller.
  FOR i IN v_old_len .. v_new_len - 1 LOOP
    v_elem := v_new -> i;
    IF jsonb_typeof(v_elem) <> 'object'
       OR NOT (v_elem ? 'type')
       OR lower(COALESCE(v_elem ->> 'changed_by', '')) IS DISTINCT FROM COALESCE(auth.uid()::text, '-') THEN
      RAISE EXCEPTION 'status_history_append_only' USING ERRCODE = '42501';
    END IF;
  END LOOP;

  RETURN NEW;
END
$$;

REVOKE EXECUTE ON FUNCTION public.guard_status_history_append_only() FROM PUBLIC, anon, authenticated;

DROP TRIGGER IF EXISTS status_history_append_only ON public.transaction_submissions;
CREATE TRIGGER status_history_append_only
  BEFORE INSERT OR UPDATE ON public.transaction_submissions
  FOR EACH ROW EXECUTE FUNCTION public.guard_status_history_append_only();
